    private String marker(JsonNode request){java.util.regex.Matcher matcher=java.util.regex.Pattern.compile("CHILD_WRITE_([A-Z])").matcher(request.toString());if(!matcher.find())throw new IllegalStateException("Missing child marker");return matcher.group(1);}
