    private boolean research(JsonNode request){return request.path("tools").toString().contains("emit_research_finding");}
    private boolean child(JsonNode request){return request.toString().contains("CHILD_WRITE_")&&!request.path("tools").toString().contains("collaboration_control");}
    @Override protected void observeModelRequest(JsonNode request){if(research(request))researchCalls.incrementAndGet();else if(child(request)){childCalls.incrementAndGet();unitCalls.computeIfAbsent(marker(request),key->new AtomicInteger()).incrementAndGet();}else{parentCalls.incrementAndGet();parentRequests.add(request);}}
    @Override protected void awaitModelPermit(JsonNode request)throws java.io.IOException{if(research(request)||child(request))return;try{if(!releaseModel.tryAcquire(90,java.util.concurrent.TimeUnit.SECONDS))throw new java.io.IOException("Writable fixture gate timed out");}catch(InterruptedException stopped){Thread.currentThread().interrupt();throw new java.io.IOException(stopped);}}
    @Override protected void await(Check check,String message)throws Exception{long end=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(60);while(System.nanoTime()<end){if(check.get())return;Thread.sleep(100);}Assert.fail(message);}
    @Override protected ObjectNode replyForModel(JsonNode request){
        if(request.toString().contains("Explain README turn "))return super.replyForModel(request);
        if(research(request)){JsonNode messages=request.path("messages");if(!messages.get(messages.size()-1).has("tool_call_id"))return tool("workspace_read",mapper.createObjectNode().put("path",researchPath(request)));ObjectNode finding=mapper.createObjectNode().put("summary",request.toString().contains("MODEL_REVISION_X")?"{\"schemaVersion\":\"collaboration-resolution-proposal/1\",\"resolutions\":[{\"path\":\"x.txt\",\"choice\":\"MANUAL\",\"text\":\"v2\"}]}":"The fixed integration file is v2 and satisfies the original required goal.").put("confidence","high");finding.putArray("evidenceRefs").add("obs/1");finding.putArray("candidatePaths").add(researchPath(request));ObjectNode claim=finding.putArray("claims").addObject().put("claimId","fixed-content").put("statement","The observed proposed or integration bytes are v2").put("inferred",false).put("confidence","high");claim.putArray("evidenceRefs").add("obs/1");return tool("emit_research_finding",finding);}
        if(child(request)){String marker=marker(request),path=marker.toLowerCase(Locale.ROOT)+".txt";int n=unitCalls.get(marker).get();if("D".equals(marker)){if(n==1)return tool("workspace_read",mapper.createObjectNode().put("path","a.txt"));n--;}if(n==1)return tool("workspace_read",mapper.createObjectNode().put("path",path));if(n==2){ObjectNode args=mapper.createObjectNode().put("path",path);args.putArray("edits").addObject().put("oldText","v1").put("newText",repairFixture()?"broken":"v2");return tool("workspace_edit",args);}return mapper.createObjectNode().put("role","assistant").put("content","Changed the scoped file from v1 to v2 inside the candidate stage.");}
        int n=parentCalls.get();if(n<=3)return tool("workspace_read",mapper.createObjectNode().put("path","x.txt"));return mapper.createObjectNode().put("role","assistant").put("content","The adopted content is v2 and its real compile verification passed.");
    }
    private ObjectNode tool(String name,ObjectNode args){ObjectNode message=mapper.createObjectNode().put("role","assistant");ObjectNode call=message.putArray("tool_calls").addObject().put("id","tool-"+UUID.randomUUID()).put("type","function");call.putObject("function").put("name",name).put("arguments",args.toString());return message;}
