    protected void assertChildHistory(String parentRun,JsonNode child)throws Exception {
        if(!Arrays.asList("CANDIDATE_READY","NO_CHANGES").contains(child.path("state").asText()))return;
        String sid=child.path("sessionId").asText();JsonNode session=api("GET","/api/v2/sessions/"+sid,null,b,null,200);int objectives=0,answers=0;
        Assert.assertEquals(fixtureServices().tasks.observationRun(parentRun).sessionId,session.path("parentSessionId").asText());
        for(JsonNode message:session.path("messages")){
            Assert.assertTrue("Child history must not manufacture a top-level Run",message.path("runId").isNull()||message.path("runId").isMissingNode());
            if(message.path("id").equals(child.path("objectiveMessageId"))){objectives++;Assert.assertEquals("user",message.path("role").asText().toLowerCase(Locale.ROOT));}
            if(message.path("id").equals(child.path("resultMessageId"))){answers++;Assert.assertEquals("assistant",message.path("role").asText().toLowerCase(Locale.ROOT));}
        }
        Assert.assertEquals(session.toString(),1,objectives);Assert.assertEquals(session.toString(),1,answers);Assert.assertFalse(child.path("agentProfileId").asText().isEmpty());Assert.assertFalse(child.path("modelPin").asText().isEmpty());
        Assert.assertTrue(child.toString(),child.path("childBudget").path("LOGICAL_CALL").path("attemptSpent").asLong()>0);Assert.assertTrue(child.path("childBudget").path("HTTP_REQUEST").path("attemptSpent").asLong()>0);
        JsonNode replay=api("GET","/api/v2/sessions/"+sid,null,b,null,200);Assert.assertEquals(session.path("messages"),replay.path("messages"));
    }
    protected void awaitReview(String group,String reviewId)throws Exception{await(()->{JsonNode observed=api("GET",group+"/reviews/"+reviewId,null,b,null,200);if(Arrays.asList("FAILED","UNKNOWN").contains(observed.path("state").asText()))Assert.fail("fixture="+root+" review="+observed);return "SUCCEEDED".equals(observed.path("state").asText());},"Read-only review did not complete; fixture="+root);}

    private void addUnit(com.fasterxml.jackson.databind.node.ArrayNode units,String id,String kind,String objective,List<String> read,List<String> write,List<String> dependencies){ObjectNode unit=units.addObject().put("unitId",id).put("kind",kind).put("objective",objective).put("required",true).put("allowNoChanges",false);com.fasterxml.jackson.databind.node.ArrayNode reads=unit.putArray("readScope"),writes=unit.putArray("writeScope"),depends=unit.putArray("dependsOn");read.forEach(reads::add);write.forEach(writes::add);dependencies.forEach(depends::add);}

